//! Every documented parameter of the AE-30: where it lives in its block, how
//! it is encoded, its range, label, widget kind and display format.
//!
//! The tables come from `data/ae30.json`, generated by `tools/gen_data.py`
//! from Roland's MIDI Implementation and Parameter Guide (via the MIT-licensed
//! aerophoneCompanion project). Values are handled in two forms:
//!
//! - **raw**: the number stored on the instrument (e.g. 64 for pan centre)
//! - **value**: what the user sees, `raw - vofs` (e.g. 0 for pan centre)

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

use crate::sysex::{pack_nibbles, unpack_nibbles};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum Kind {
    #[default]
    Slider,
    Select,
    Switch,
}

/// How a value is shown.
#[derive(Debug, Clone, PartialEq, Deserialize)]
#[serde(tag = "k", rename_all = "lowercase")]
pub enum Format {
    /// `(value + add) * mul` with `dec` decimals, an optional `+` sign and a unit.
    Lin {
        add: f64,
        mul: f64,
        dec: u8,
        sign: bool,
        unit: String,
    },
    /// 0..=100 shown as `D100:0W` … `D0:100W`.
    DryWet,
    /// 0..=127 shown as `L64` … `C` … `63R`.
    Pan64,
    /// -64..=63 shown as `L64` … `Center` … `R63`.
    PanC,
    /// `items[value - base]`, or the plain number outside the list.
    List { items: Vec<String>, base: i32 },
}

impl Format {
    pub fn show(&self, v: i32) -> String {
        match self {
            Format::Lin {
                add,
                mul,
                dec,
                sign,
                unit,
            } => {
                let x = (f64::from(v) + add) * mul;
                let plus = if *sign && x > 0.0 { "+" } else { "" };
                format!("{plus}{x:.prec$}{unit}", prec = *dec as usize)
            }
            Format::DryWet => format!("D{}:{}W", 100 - v, v),
            Format::Pan64 => match v {
                64 => "C".into(),
                v if v < 64 => format!("L{}", 64 - v),
                v => format!("{}R", v - 64),
            },
            Format::PanC => match v {
                0 => "Center".into(),
                v if v < 0 => format!("L{}", -v),
                v => format!("R{v}"),
            },
            Format::List { items, base } => usize::try_from(v - base)
                .ok()
                .and_then(|i| items.get(i))
                .cloned()
                .unwrap_or_else(|| v.to_string()),
        }
    }
}

/// One parameter in a block.
#[derive(Debug, Clone, Deserialize)]
pub struct Param {
    /// Byte offset inside the block.
    pub off: u32,
    /// Bytes on the wire.
    pub n: u8,
    /// Bits used per byte: 7 for plain bytes, 4 for nibbles.
    pub bits: u8,
    /// Name in Roland's MIDI Implementation.
    pub name: String,
    /// Friendlier label from the Parameter Guide, when there is one.
    pub label: Option<String>,
    #[serde(default)]
    pub kind: Kind,
    #[serde(default)]
    pub opts: Vec<String>,
    pub fmt: Option<Format>,
    /// For effect parameters: the effect type this meaning applies to.
    pub fx: Option<u16>,
    /// A placeholder like "MFX Parameter 3", whose meaning depends on the type.
    #[serde(default)]
    pub generic: bool,
    pub vofs: i32,
    pub min: i32,
    pub max: i32,
}

impl Param {
    pub fn label(&self) -> &str {
        self.label.as_deref().unwrap_or(&self.name)
    }

    /// Bytes this parameter occupies in its block.
    pub fn len(&self) -> usize {
        self.n as usize
    }

    pub fn is_empty(&self) -> bool {
        self.n == 0
    }

    fn raw_from(&self, bytes: &[u8]) -> i32 {
        match (self.n, self.bits) {
            (1, _) => i32::from(bytes[0] & 0x7F),
            (_, 4) => unpack_nibbles(bytes) as i32,
            _ => bytes
                .iter()
                .fold(0i32, |acc, &b| (acc << 7) | i32::from(b & 0x7F)),
        }
    }

    /// The raw number stored for this parameter in `block`.
    pub fn raw(&self, block: &[u8]) -> Option<i32> {
        let start = self.off as usize;
        block
            .get(start..start + self.len())
            .map(|b| self.raw_from(b))
    }

    /// The value the user sees, read from `block`.
    pub fn get(&self, block: &[u8]) -> Option<i32> {
        self.raw(block).map(|r| r - self.vofs)
    }

    pub fn clamp(&self, value: i32) -> i32 {
        value.clamp(self.min, self.max.max(self.min))
    }

    /// The wire bytes for `value` (clamped to the range).
    pub fn encode(&self, value: i32) -> Vec<u8> {
        let raw = (self.clamp(value) + self.vofs).max(0) as u32;
        match (self.n, self.bits) {
            (1, _) => vec![(raw & 0x7F) as u8],
            (n, 4) => pack_nibbles(raw, n as usize),
            (n, _) => (0..n)
                .rev()
                .map(|i| ((raw >> (7 * u32::from(i))) & 0x7F) as u8)
                .collect(),
        }
    }

    /// Store `value` into `block`; returns the bytes written.
    pub fn set(&self, block: &mut [u8], value: i32) -> Vec<u8> {
        let bytes = self.encode(value);
        let start = self.off as usize;
        if let Some(dst) = block.get_mut(start..start + bytes.len()) {
            dst.copy_from_slice(&bytes);
        }
        bytes
    }

    /// `value` as the user should see it.
    pub fn show(&self, value: i32) -> String {
        if !self.opts.is_empty() {
            if let Some(o) = usize::try_from(value).ok().and_then(|i| self.opts.get(i)) {
                return o.clone();
            }
        }
        match &self.fmt {
            Some(f) => f.show(value),
            None => value.to_string(),
        }
    }

    pub fn is_choice(&self) -> bool {
        !self.opts.is_empty()
    }
}

/// A kind of block: its size and parameters.
#[derive(Debug, Clone, Deserialize)]
pub struct Table {
    pub size: u32,
    pub params: Vec<Param>,
}

impl Table {
    /// The parameter at `off` that always applies (not effect-type specific).
    pub fn at(&self, off: u32) -> Option<&Param> {
        self.params.iter().find(|p| p.off == off && p.fx.is_none())
    }

    /// The parameter called `name` (Roland's name or the label).
    pub fn named(&self, name: &str) -> Option<&Param> {
        self.params
            .iter()
            .find(|p| p.fx.is_none() && (p.name == name || p.label() == name))
    }

    /// Parameters that always apply.
    pub fn fixed(&self) -> impl Iterator<Item = &Param> {
        self.params.iter().filter(|p| p.fx.is_none() && !p.generic)
    }

    /// The parameters of effect type `fx`; the generic slots if the type
    /// has no documented parameters.
    pub fn for_fx(&self, fx: u16) -> Vec<&Param> {
        let typed: Vec<&Param> = self.params.iter().filter(|p| p.fx == Some(fx)).collect();
        if typed.is_empty() {
            self.params.iter().filter(|p| p.generic).collect()
        } else {
            typed
        }
    }
}

/// One block in an area's layout (e.g. `Perf_part_3` at `00 32 00`).
#[derive(Debug, Clone, Deserialize)]
pub struct LayoutEntry {
    pub name: String,
    pub table: String,
    /// Offset from the area's base, as a plain number.
    pub off: u32,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Layouts {
    pub system: Vec<LayoutEntry>,
    pub setup: Vec<LayoutEntry>,
    pub scene: Vec<LayoutEntry>,
    pub tone: Vec<LayoutEntry>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct FxType {
    pub id: u16,
    pub name: String,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "UPPERCASE")]
pub struct FxTypes {
    pub mfx: Vec<FxType>,
    pub cho: Vec<FxType>,
    pub dly: Vec<FxType>,
    pub rev: Vec<FxType>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Data {
    pub layouts: Layouts,
    pub tables: HashMap<String, Table>,
    pub fx: FxTypes,
    /// Preset tone names by bank: A, B, C (ZEN-Core), SN, DK.
    pub tones: HashMap<String, Vec<String>>,
    pub tone_cats: HashMap<String, Vec<String>>,
    pub cc_names: Vec<String>,
    pub waves: HashMap<String, Vec<String>>,
    pub wave_groups: HashMap<String, u32>,
}

impl Data {
    pub fn table(&self, name: &str) -> &Table {
        self.tables
            .get(name)
            .unwrap_or_else(|| panic!("no parameter table {name}"))
    }

    /// The name of a preset tone, if known.
    pub fn tone_name(&self, msb: u8, lsb: u8, pc: u8) -> Option<&str> {
        let bank = match (msb, lsb) {
            (71, 72) => "A",
            (71, 73) => "B",
            (71, 74) => "C",
            (89, 66) => "SN",
            (70, 66) => "DK",
            _ => return None,
        };
        self.tones
            .get(bank)?
            .get(pc as usize)
            .map(String::as_str)
            .filter(|s| !s.is_empty())
    }

    pub fn tone_category(&self, msb: u8, lsb: u8, pc: u8) -> Option<&str> {
        let bank = match (msb, lsb) {
            (71, 72) => "A",
            (71, 73) => "B",
            (71, 74) => "C",
            (89, 66) => "SN",
            (70, 66) => "DK",
            _ => return None,
        };
        self.tone_cats
            .get(bank)?
            .get(pc as usize)
            .map(String::as_str)
            .filter(|s| !s.is_empty())
    }
}

/// The parameter data, loaded on first use.
pub fn data() -> &'static Data {
    static DATA: OnceLock<Data> = OnceLock::new();
    DATA.get_or_init(|| {
        serde_json::from_str(include_str!("../data/ae30.json")).expect("data/ae30.json is valid")
    })
}
